import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { lawsApi } from '../services/api';
import './LawDetail.css';

const LawDetail = () => {
  const { id } = useParams();
  const [law, setLaw] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchLaw = async () => {
      try {
        setLoading(true);
        const data = await lawsApi.getLawById(id);
        setLaw(data);
        setError(null);
      } catch (err) {
        setError('خطا در دریافت اطلاعات قانون. لطفا دوباره تلاش کنید.');
        console.error(`Error fetching law with ID ${id}:`, err);
      } finally {
        setLoading(false);
      }
    };

    fetchLaw();
  }, [id]);

  const fetchArticlesFromAI = async () => {
    try {
      setLoading(true);
      const response = await lawsApi.fetchArticles(id);
      setLaw(response.law);
      setError(null);
    } catch (err) {
      setError('خطا در دریافت ماده های قانون از TogetherAI. لطفا دوباره تلاش کنید.');
      console.error(`Error fetching articles for law ID ${id} from TogetherAI:`, err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="loading">در حال بارگذاری...</div>;
  }

  if (error) {
    return <div className="error">{error}</div>;
  }

  if (!law) {
    return <div className="error">قانون مورد نظر یافت نشد.</div>;
  }

  return (
    <div className="law-detail">
      <Link to="/laws" className="back-link">
        بازگشت به فهرست قوانین
      </Link>

      <div className="law-header">
        <h1>{law.title}</h1>
        <div className="law-meta">
          <span className="category">دسته: {law.category}</span>
        </div>
      </div>

      <div className="law-content">
        <div className="description">
          <h3>توضیحات قانون</h3>
          <p>{law.description}</p>
        </div>

        <div className="articles-section">
          <div className="articles-header">
            <h3>ماده های قانون</h3>
            {law.articles.length === 0 && (
              <button onClick={fetchArticlesFromAI} className="fetch-btn">
                دریافت ماده های قانون از TogetherAI
              </button>
            )}
          </div>

          {law.articles.length > 0 ? (
            <div className="articles-list">
              {law.articles.map((article, index) => (
                <div className="article-item" key={index}>
                  <h4>ماده {article.articleNumber}</h4>
                  <p>{article.content}</p>
                </div>
              ))}
            </div>
          ) : (
            <div className="no-articles">
              <p>هیچ ماده ای برای این قانون وجود ندارد.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default LawDetail;
